edits.newText:
// --- Collision (tested primitive + swept resolution, see #1) ---------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit — the face is derived from the penetration in
// `resolveBounce` (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Penetration of the ball's box into the brick, per face, in pixels.
function penetration(ball, brick) {
  return {
    left: ball.x + ball.r - brick.x,
    right: brick.x + brick.w - (ball.x - ball.r),
    top: ball.y + ball.r - brick.y,
    bottom: brick.y + brick.h - (ball.y - ball.r),
  };
}

// Equal-penetration tolerance. Below this, a hit is a diagonal corner hit and
// BOTH components flip; otherwise only the axis with the smaller penetration
// bounces (per-face rule).
const CORNER_EPS = 1e-9;

// Flips the velocity along the face(s) actually hit and pushes the ball just
// outside the brick, so it cannot still overlap on the next frame (sticky
// bounce, see #1).
//   per face: the axis with the smaller penetration is the face hit — flip
//             `vy` on a top/bottom hit, `vx` on a side hit, leave the other
//             component exactly as it was;
//   corner:   equal penetrations mean a diagonal hit — flip both components;
//   leaving:  a ball already moving away on every candidate axis is not
//             bounced (it slides out on its own).
// Returns `true` when a bounce happened.
function resolveBounce(ball, brick, pen) {
  const minH = Math.min(pen.left, pen.right);
  const minV = Math.min(pen.top, pen.bottom);
  const hFace = pen.left <= pen.right ? 'left' : 'right';
  const vFace = pen.top <= pen.bottom ? 'top' : 'bottom';
  const intoX = hFace === 'left' ? ball.vx > 0 : ball.vx < 0;
  const intoY = vFace === 'top' ? ball.vy > 0 : ball.vy < 0;

  // Corner: diagonal hit, both components flip.
  if (Math.abs(minH - minV) <= CORNER_EPS && intoX && intoY) {
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    if (minH <= minV) {
      ball.x = hFace === 'left' ? brick.x - ball.r : brick.x + brick.w + ball.r;
    } else {
      ball.y = vFace === 'top' ? brick.y - ball.r : brick.y + brick.h + ball.r;
    }
    return true;
  }

  // Side hit: flip `vx` only, push out horizontally.
  if (minH <= minV && intoX) {
    ball.vx = -ball.vx;
    ball.x = hFace === 'left' ? brick.x - ball.r : brick.x + brick.w + ball.r;
    return true;
  }

  // Top/bottom hit: flip `vy` only, push out vertically.
  if (minV <= minH && intoY) {
    ball.vy = -ball.vy;
    ball.y = vFace === 'top' ? brick.y - ball.r : brick.y + brick.h + ball.r;
    return true;
  }

  return false;
}

// Sweeps the ball's path from (px, py) — its position at the start of the
// step — to its current position, and resolves the FIRST contact. Tunnelling
// is discrete-position blindness: at level 6 a stuttered frame moves the ball
// 35.5 px against 34 px to cross a brick (`BRICK_H` + diameter), so sampling
// only before/after the move would jump straight over it.
//
// The grid gap (`BRICK_GAP` = 8 px) is narrower than the ball's diameter
// (14 px), so a seam overlaps TWO bricks in the same pass: only ONE bounce is
// applied per step, otherwise `vy = -vy` applied twice cancels out and the
// ball goes straight through (see #1, "neighbours").
function resolveBricks(state, px, py) {
  const { ball, bricks } = state;

  const dx = ball.x - px;
  const dy = ball.y - py;
  const dist = Math.hypot(dx, dy);

  // Sub-steps small enough that the ball can never jump over a brick face
  // (`BALL_R` = 7 px < `BRICK_H` = 20 px). The worst case — level 6, a 50 ms
  // stuttered frame — is a 35.5 px move, i.e. at most 6 samples.
  const steps = Math.max(1, Math.ceil(dist / BALL_R));

  for (let i = 0; i <= steps; i++) {
    ball.x = px + (dx * i) / steps;
    ball.y = py + (dy * i) / steps;

    // First sample that touches any brick: keep the one with the smallest
    // penetration — the physically meaningful hit at a seam.
    let best = null;
    let bestPen = Infinity;
    for (const brick of bricks) {
      if (!brick.alive || !collides(ball, brick)) continue;
      const pen = penetration(ball, brick);
      const minPen = Math.min(pen.left, pen.right, pen.top, pen.bottom);
      if (minPen < bestPen) {
        bestPen = minPen;
        best = { brick, pen };
      }
    }
    if (!best) continue;
    if (!resolveBounce(ball, best.brick, best.pen)) continue;

    best.brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(best.brick, state.combo);
    return; // exactly one bounce per step
  }
}

